-- STORY-051 — the remaining AUX rule rows, AUX-R-008..034 (aux-and-geo-analysis.md section 2), so the catalog holds all six
-- categories and the load-time weight assertion (NFR-AUX-03) can require every one of them.
--   structured_data 0.14+0.10+0.12+0.07+0.09+0.11+0.09+0.06+0.06+0.08+0.08 = 1.000
--   context_fitness 0.16+0.15+0.22+0.11+0.13+0.09+0.14                     = 1.000
--   render_mode     0.34+0.28+0.22+0.16                                    = 1.000
--   freshness       0.50+0.50                                              = 1.000
--   entity_clarity  0.34+0.30+0.36                                         = 1.000
-- and the category weights 0.28+0.22+0.20+0.15+0.06+0.09 = 1.000.
--
-- `thresholds` is what each evaluator in src/lib/aux/rules reads; an evaluator holds no number of its own. Rows for rules the
-- document model cannot yet decide (AUX-R-028, -031, -032, -033, -034: see STORY-051) are present so the weights sum, and are
-- reported as not evaluated rather than silently passing.
--
-- AUX-R-006 is re-stated with the directive list it matches (it carried '{}' in 0070), under the new rule_version.
-- AUX-R-029 max_bytes is 3 MiB (3 * 1024 * 1024 = 3145728): the reference's "3 MB" is read as binary megabytes, as a browser or `ls -h`
-- reports a page size. DECISION TO CONFIRM in the reference; a page of 3,000,000 to 3,145,728 bytes passes under this reading.
-- Subtype membership (a BlogPosting is an Article, a LocalBusiness an Organization) is DATA: the type lists in AUX-R-010..014 and -018.
-- aux_rule_catalog is GLOBAL (no workspace_id): no RLS. ON CONFLICT takes over any row the demo seed inserted first.
INSERT INTO aux_rule_catalog
  (code, category, title, description, rationale, severity_default, weight, auto_fixable, thresholds, task_threshold, rule_version)
VALUES
  ('AUX-R-006', 'crawler_access', 'Pages tell AI engines not to use them',
   'X-Robots-Tag or a robots meta tag contains noai, noimageai or noarchive on a tracked page.',
   'AI engines that honour these directives will not use or cite the page in their answers.',
   'high', 0.12, true, '{"directives":["noai","noimageai","noarchive"],"min_matches":1}'::jsonb, 'high', '2026.10.2'),
  ('AUX-R-008', 'structured_data', 'Your structured data is broken',
   'A JSON-LD block on the page is not valid JSON.',
   'AI engines that read structured data skip a block they cannot parse, so the facts in it are never used to describe you.',
   'critical', 0.14, true, '{"min_errors":1}'::jsonb, 'critical', '2026.10.2'),
  ('AUX-R-009', 'structured_data', 'Your structured data does not say what it describes',
   'A JSON-LD block has no @context, or an entity in it has no @type.',
   'AI engines cannot tell what kind of thing the data describes, so they ignore it rather than risk misreading it.',
   'high', 0.10, true, '{"min_blocks":1}'::jsonb, 'high', '2026.10.2'),
  ('AUX-R-010', 'structured_data', 'No structured description of what this page is about',
   'The page declares none of Organization, Product, SoftwareApplication, Service or Article.',
   'Without a declared entity, AI engines have to guess what the page is about and whose it is, and they guess less often in your favour.',
   'high', 0.12, true, '{"primary_types":["Organization","Corporation","LocalBusiness","NGO","EducationalOrganization","GovernmentOrganization","NewsMediaOrganization","OnlineBusiness","OnlineStore","Store","Restaurant","ProfessionalService","FinancialService","LegalService","MedicalBusiness","SportsOrganization","Product","ProductGroup","ProductModel","SoftwareApplication","WebApplication","MobileApplication","VideoGame","Service","FinancialProduct","Article","BlogPosting","NewsArticle","TechArticle","Report","ScholarlyArticle","SocialMediaPosting","LiveBlogPosting"]}'::jsonb, 'high', '2026.10.3'),
  ('AUX-R-011', 'structured_data', 'Your organization description is thin',
   'The Organization markup is missing two or more of name, url, logo, sameAs and description.',
   'AI engines build their picture of your company from these fields, so a missing one is a fact they state without you or leave out.',
   'medium', 0.07, true, '{"entity_types":["Organization","Corporation","LocalBusiness","NGO","EducationalOrganization","GovernmentOrganization","NewsMediaOrganization","OnlineBusiness","OnlineStore","Store","Restaurant","ProfessionalService","FinancialService","LegalService","MedicalBusiness","SportsOrganization"],"fields":["name","url","logo","sameAs","description"],"min_missing":2}'::jsonb, 'medium', '2026.10.3'),
  ('AUX-R-012', 'structured_data', 'Engines can name your product but cannot show its price',
   'The product or service markup has no offers, or the offers lack price and priceCurrency, on a page that talks about pricing.',
   'AI engines asked what you cost cannot quote a price they cannot read from your data, so they quote a competitor or a guess.',
   'high', 0.09, true, '{"entity_types":["Product","SoftwareApplication","WebApplication","MobileApplication","VideoGame","Service","ProfessionalService","FinancialProduct"],"currency_symbols":"$€£¥₹","currency_codes":["USD","EUR","GBP","JPY","INR","CAD","AUD"],"price_context_words":["price","prices","pricing","plan","plans","cost","costs","per month","per year","per user","per seat","/mo","/month","/year","monthly","annually","starts at","starting at"],"context_window_chars":40,"price_units":["per month","per year","per user","per seat","/mo","/month","/year"]}'::jsonb, 'high', '2026.10.3'),
  ('AUX-R-013', 'structured_data', 'Your structured data contradicts your page',
   'The price, name or rating in the structured data disagrees with the text visitors see.',
   'AI engines that find two different answers lose trust in both, and may stop citing the page or cite the wrong figure.',
   'critical', 0.11, false, '{"name_entity_types":["Product","SoftwareApplication","WebApplication","MobileApplication","VideoGame","Service","ProfessionalService","FinancialProduct"],"currency_symbols":"$€£¥₹","currency_codes":["USD","EUR","GBP","JPY","INR","CAD","AUD"],"min_disagreements":1,"price_tolerance":0.005,"rating_tolerance":0.005,"price_context_words":["price","pricing","per month","per year","per user","per seat","/mo","/month","/year","monthly","annually","starts at","starting at"],"rating_scales":[5,10],"rating_context_words":["rated","rating","ratings","stars","star","review","reviews"],"context_window_chars":40,"free_words":["free","free forever","$0"],"article_types":["Article","NewsArticle","BlogPosting","TechArticle","ScholarlyArticle","Report","SocialMediaPosting","LiveBlogPosting"]}'::jsonb, 'critical', '2026.10.3'),
  ('AUX-R-014', 'structured_data', 'Your feature list is missing or covers too little',
   'A software or product page has no featureList, or the featureList covers fewer than half of the page capability headings.',
   'AI engines answering what your product can do read the feature list, so a capability missing from it is one they do not credit you with.',
   'high', 0.09, true, '{"entity_types":["Product","SoftwareApplication","WebApplication","MobileApplication","VideoGame"],"min_coverage":0.5,"heading_levels":[2,3],"non_capability_headings":["pricing","faq","frequently asked questions","contact","about","reviews","testimonials","blog","careers"]}'::jsonb, 'high', '2026.10.3'),
  ('AUX-R-015', 'structured_data', 'A star rating with nothing behind it',
   'The structured data asserts a rating with no review count and no source.',
   'AI engines discount a rating they cannot trace to reviews, and an unbacked one can make the rest of your data look unreliable.',
   'medium', 0.06, true, '{"provenance_keys":["reviewCount","ratingCount","url","author","publisher","sameAs"]}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-016', 'structured_data', 'Your structured data uses terms engines do not know',
   'The markup uses a vocabulary other than schema.org, a type that is not a schema.org class, or a deprecated property.',
   'AI engines only understand the shared vocabulary, so data written in anything else is read as nothing.',
   'medium', 0.06, true, '{"schema_hosts":["schema.org"],"deprecated_properties":["subEvents"]}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-017', 'structured_data', 'Questions on the page are not marked up as questions',
   'The page has three or more question headings and no FAQPage or QAPage markup.',
   'AI engines look for marked-up questions and answers to quote, so yours are passed over for pages that label them.',
   'medium', 0.08, true, '{"min_headings":3,"heading_levels":[2,3]}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-018', 'structured_data', 'Your structured data describes you two different ways',
   'Two JSON-LD blocks declare the same type with different names or URLs.',
   'AI engines that see two conflicting descriptions of one thing may merge them wrongly or trust neither.',
   'medium', 0.08, true, '{"min_conflicts":1,"singleton_types":["Organization","Corporation","LocalBusiness","WebSite","SoftwareApplication","WebApplication","MobileApplication","Service","Article","BlogPosting","NewsArticle","TechArticle"]}'::jsonb, 'medium', '2026.10.3'),
  ('AUX-R-019', 'context_fitness', 'The page is too long for an engine to read whole',
   'The rendered page is more than 12,000 tokens (critical above 25,000).',
   'AI engines read a limited amount of a page, so on a very long one the part they cut may be the part you wanted cited.',
   'high', 0.16, false, '{"warn_tokens":12000,"critical_tokens":25000}'::jsonb, 'high', '2026.10.2'),
  ('AUX-R-020', 'context_fitness', 'Little of the page is the content itself',
   'Less than 35% of the tokens on the rendered page are main content.',
   'AI engines spend their reading budget on menus and boilerplate before they reach what you want them to cite.',
   'high', 0.15, false, '{"min_ratio":0.35}'::jsonb, 'high', '2026.10.2'),
  ('AUX-R-021', 'context_fitness', 'A section runs on long enough to be cut mid-thought',
   'A heading section is over 1,800 tokens with no subheading, list or table (critical above 3,000).',
   'AI engines split pages into chunks, and a long unbroken section is cut at an arbitrary point, so the quote they use may be half an answer.',
   'high', 0.22, false, '{"warn_tokens":1800,"critical_tokens":3000}'::jsonb, 'high', '2026.10.2'),
  ('AUX-R-022', 'context_fitness', 'Paragraphs and sentences are too long to quote',
   'A paragraph is over 900 characters, or a section averages more than 32 words per sentence.',
   'AI engines quote short, self-contained passages, so dense text is skipped for a competitor that is easier to lift from.',
   'medium', 0.11, false, '{"max_paragraph_chars":900,"max_mean_sentence_words":32}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-023', 'context_fitness', 'No quick answer at the top of the page',
   'The first 400 tokens contain no table, definition list, numbered list or short summary paragraph.',
   'AI engines favour pages that answer in the opening lines, and take the answer from a page that does when yours does not.',
   'medium', 0.13, true, '{"window_tokens":400,"max_summary_sentences":3}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-024', 'context_fitness', 'The headings do not form a clear outline',
   'The page has no H1, more than one H1, or skips a heading level.',
   'AI engines use headings to understand what each part of a page answers, so a broken outline blurs what they quote you for.',
   'medium', 0.09, true, '{"max_h1":1,"max_level_step":1}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-025', 'context_fitness', 'Key facts are only in pictures',
   'Pricing, capability or comparison content is in an image with no nearby text and an alt text under 20 characters.',
   'AI engines do not read images, so the facts in them are invisible and the engine answers from another page instead.',
   'high', 0.14, false, '{"min_alt_chars":20,"min_adjacent_chars":20,"adjacent_window_chars":300,"keywords":["pricing","price","plans","comparison","compare","features","feature"]}'::jsonb, 'high', '2026.10.2'),
  ('AUX-R-026', 'render_mode', 'Most of the page only exists after scripts run',
   'More than 30% of the page main content is absent from the plain HTML (critical above 60%).',
   'AI crawlers that do not run scripts see a mostly empty page, so there is little to cite you for.',
   'high', 0.34, false, '{"warn_ratio":0.3,"critical_ratio":0.6}'::jsonb, 'high', '2026.10.2'),
  ('AUX-R-027', 'render_mode', 'Your structured data is added by scripts only',
   'JSON-LD appears in the rendered page but not in the plain HTML.',
   'AI crawlers that do not run scripts never see the structured data, so it does nothing for how they describe you.',
   'critical', 0.28, false, '{"min_missing_blocks":1}'::jsonb, 'critical', '2026.10.2'),
  ('AUX-R-028', 'render_mode', 'Content hidden behind a click or scroll',
   'Tracked content appears only after a click or scroll and is absent from the plain HTML.',
   'AI crawlers do not click or scroll, so content behind an interaction is never read.',
   'high', 0.22, false, '{}'::jsonb, 'high', '2026.10.2'),
  ('AUX-R-029', 'render_mode', 'The page is slow or heavy for a crawler',
   'The first byte takes over 1,500 ms, the load over 8,000 ms, or the page is over 3 MB.',
   'AI crawlers give up on slow or very large pages, so the page may not be read at all.',
   'medium', 0.16, false, '{"max_ttfb_ms":1500,"max_load_ms":8000,"max_bytes":3145728}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-030', 'freshness', 'Nothing tells engines when the page was last updated',
   'There is no dateModified in the structured data and no visible last-updated date.',
   'AI engines prefer recent sources and cannot tell that yours is current, so they favour a page that shows its date.',
   'medium', 0.50, true, '{"visible_date_labels":["last updated","updated","last modified","modified","revised"]}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-031', 'freshness', 'The page is older than what engines cite in your category',
   'The page is more than 365 days old, or more than 180 days older than the median of the pages engines cite.',
   'AI engines favour fresher sources, so a stale page loses citations to newer competitors.',
   'medium', 0.50, false, '{"max_age_days":365,"max_corpus_gap_days":180}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-032', 'entity_clarity', 'Your brand name is missing from the title and main heading',
   'Neither the title nor the H1 contains a brand name.',
   'AI engines tie a page to a brand through its title and main heading, so an unnamed page is not credited to you.',
   'medium', 0.34, true, '{}'::jsonb, 'medium', '2026.10.2'),
  ('AUX-R-033', 'entity_clarity', 'The page says our platform instead of naming it',
   'More than 60% of the sentences about what the product does use pronouns or our platform instead of its name.',
   'AI engines cannot attach a capability to a product that is never named in the sentence, so they do not credit it to you.',
   'low', 0.30, false, '{"max_unnamed_ratio":0.6}'::jsonb, 'low', '2026.10.2'),
  ('AUX-R-034', 'entity_clarity', 'Nothing links you to your official profiles',
   'No sameAs link to an authoritative profile exists anywhere on the domain.',
   'AI engines confirm who you are by matching you to profiles they already trust, and cannot confirm an entity they cannot match.',
   'medium', 0.36, true, '{}'::jsonb, 'medium', '2026.10.2')
ON CONFLICT (code) DO UPDATE SET
  category          = EXCLUDED.category,
  title             = EXCLUDED.title,
  description       = EXCLUDED.description,
  rationale         = EXCLUDED.rationale,
  severity_default  = EXCLUDED.severity_default,
  weight            = EXCLUDED.weight,
  auto_fixable      = EXCLUDED.auto_fixable,
  thresholds        = EXCLUDED.thresholds,
  task_threshold    = EXCLUDED.task_threshold,
  rule_version      = EXCLUDED.rule_version;
